package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAsianArtBank1 {
    private const val T = "පෙරදිග ආසියාතික කලාව (ඉන්දියාව, චීනය, ජපානය)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ මොහෙන්ජො-දාරෝ නගරයෙන් හමුවූ ලෝකඩ 'නැටුම් කාරිය' (Dancing Girl) ප්‍රතිමාවේ උස කොපමණද?", "සෙන්ටිමීටර 10.5 ක් පමණ ඉතා කුඩා ප්‍රතිමාවකි", "මීටර 10 ක් උස යෝධ ප්‍රතිමාවකි", "මීටර 3 ක් උස කළුගල් පිළිමයකි", "සෙන්ටිමීටර 1 ක මුද්දකි", "ක්‍රි.පූ. 2500 පමණ කාලයට අයත් මෙම සියුම් ලෝකඩ ප්‍රතිමාව අඟල් 4ක් පමණ උස කෘතියකි."),
        q("මොහෙන්ජො-දාරෝ 'නැටුම් කාරිය' ප්‍රතිමාව නිර්මාණය කිරීමට ඉන්දු නිම්න ශිල්පීන් භාවිත කළ ලෝහ වාත්තු තාක්ෂණය කුමක්ද?", "මැකී යන ඉටි ක්‍රමය (Lost-wax Casting)", "කළුගලින් හාරා නෙළීම", "මැටි පුළුස්සා තීන්ත ගෑම", "රන් තහඩු කැපීම", "ඉටි අච්චුවක් සාදා මැටි තවරා ලෝකඩ වත් කරන ලොස්ට්-වැක්ස් ක්‍රමය ඉන්දු නිම්න ශිල්පීහු දැන සිටියහ."),
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයෙන් හමුවූ සුදු සබන් ගලින් (Steatite) නෙළන ලද 'පූජක රජු' (Priest-King) ප්‍රතිමාවේ විශේෂ ලක්ෂණය කුමක්ද?", "ත්‍රිපත්‍ර මල් සළුව හා රැවුල", "අත් සතරක් සහිතව නැටීම", "කඩුවක් ඔසවා අසු පිට සිටීම", "හිස රහිතව පියාපත් තිබීම", "අඩවන් දෑස්, පටියක් බැඳි හිස හා ත්‍රිපත්‍ර මෝස්තර සළුව පූජක රජු ප්‍රතිමාවේ කැපී පෙනේ."),
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ හමුවූ 'පශුපති මුද්‍රාවේ' (Pashupati Seal) නිරූපණය කර ඇත්තේ කුමක්ද?", "සතුන් පිරිවරාගෙන යෝගී ඉරියව්වෙන් වැඩ සිටින අං සහිත රුවක්", "ඔලිම්පික් දිවීමේ තරගයක්", "පිරමීඩ ගොඩනගන වහලුන් පිරිසක්", "බුදුන් වහන්සේගේ පරිනිර්වාණය", "ඇතා, ව්‍යාඝ්‍රයා, රයිනෝ හා මී හරකා වට කරගත් යෝගී රුව පසුකාලීන ශිව සංකල්පයේ මූලාරම්භය ලෙස සැලකේ."),
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ හරප්පා හා මොහෙන්ජො-දාරෝ මුද්‍රා (Seals) ප්‍රධාන වශයෙන් සාදා ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "ස්ටීටයිට් (මෘදු සබන් ගල)", "දැඩි දියමන්ති ගලින්", "වීදුරු හා ප්ලාස්ටික්වලින්", "ඔප දැමූ යකඩ තහඩුවලින්", "ඒකශෘංග ගවයා, කුදු ගොනා ආදී රූප හා නොකියවූ අක්ෂර මෘදු සබන් ගල් මුද්‍රාවල කොටා පුළුස්සා ඇත."),
        q("හරප්පා නගරයෙන් හමුවූ රතු වැලිගලින් නෙළන ලද නිරුවත් 'පුරුෂ කඳ' (Male Torso) ප්‍රතිමාවේ ඇති කලාත්මක ගුණය කුමක්ද?", "සුමට මාංශපේශී නෙළා තිබීම", "පැතලි ජ්‍යාමිතික රූපයක් වීම", "කොළ පැහැති සායම් ගා තිබීම", "ලෝහ කම්බිවලින් එතීම", "වෙන් කළ හැකි හිස හා අත් සවි කිරීමට සිදුරු තිබූ මෙය ඉතා උසස් කායව්‍යවච්ඡේද අවබෝධයක් පෙන්වයි."),
        q("ඉන්දියාවේ මෞර්ය අධිරාජ්‍යයේ (ක්‍රි.පූ. 3 වන සියවස) 'අශෝක කුළුණු' ඉදි කිරීමේදී යොදා ගත් ප්‍රධාන ශිලා මාධ්‍යය කුමක්ද?", "ඔප දැමූ චුනාර් වැලිගල්", "සුදු කිරිගරුඬ පාෂාණය", "රතු ලාවා ගල් කුට්ටි", "ටෙරාකොටා පිළිස්සූ මැටි", "තනි චුනාර් වැලිගල් කුට්ටියෙන් නෙළා වීදුරුවක් මෙන් ඔප දමා ඇති අශෝක කුළුණු මෞර්ය කලාවේ විස්මයකි."),
        q("ඉන්දියාවේ 'සාරානාත් අශෝක ස්තම්භ හිසේ' (Lion Capital of Ashoka) මුදුනේ ඇති මූර්ති කොටස කුමක්ද?", "සිව් දිසාවට බැඳි සිංහ රූ සතරක්", "තනි ඇතෙකුගේ මූර්ති රුවක්", "නටන ගැහැනු මූර්ති රුවක්", "හංසයෙකුගේ මූර්ති රුවක්", "වර්තමාන ඉන්දීය ජාතික ලාංඡනයට ගෙන ඇත්තේ ධර්මචක්‍රය සහිත පාදම මත සිටින සිංහ රූප හතරයි."),
        q("සාරානාත් අශෝක ස්තම්භ හිසේ පාදමේ (Abacus) ධර්මචක්‍ර සමඟ කැටයම් කර ඇති සතුන් සතර දෙනා කවුද?", "සිංහයා, ඇතා, අශ්වයා සහ ගොනා", "මුවා, හාවා, නරියා සහ කොටියා", "මොනරා, ගිරවා, හංසයා සහ කොකා", "සර්පයා, මාළුවා, ඉබ්බා සහ කිඹුලා", "සතර දිසාව හා බුදු සිරිතේ වැදගත් සංකේත නිරූපණය කරමින් මෙම සිව්පාවුන් සහ ගරාදි 24 ධර්මචක්‍රය කොටා ඇත."),
        q("මෞර්ය යුගයට අයත් දීදාර්ගන්ජ් (Didarganj) නගරයෙන් හමුවූ 'චෞරි දාරිනී යක්ෂිණී' ප්‍රතිමාවේ කැපී පෙනෙන කලාත්මක ලක්ෂණය කුමක්ද?", "මෞර්ය ඔපය හා සුමට ස්ත්‍රී රුව", "ගොරෝසු අපැහැදිලි මැටි හැඩය", "රළු ලී කැටයමක් වීම", "කළු තීන්ත ආලේප කිරීම", "දකුණු අතින් චාමරයක් දරා සිටින චුනාර් වැලිගල් යක්ෂිණී ප්‍රතිමාව ඉන්දීය මූර්තියේ මුල් අග්‍රගණ්‍ය කෘතියකි."),
        q("ශුංග යුගයේ (ක්‍රි.පූ. 2–1 සියවස්) ඉදි වූ 'සාංචි මහා ස්තූපයේ' පිවිසුම් දොරටු සතර හඳුන්වන්නේ කුමන නමින්ද?", "තොරණ (Toranas)", "වාහල්කඩ", "ගෝපුරම්", "මිනාරට්", "බුදු සිරිත හා ජාතක කතා සියුම් කැටයමින් අලංකාර කළ ගල් තොරණ සතර සාංචි ස්තූපය වටා පිහිටයි."),
        q("භාරුත් හා සාංචි තොරණ කැටයම්වල බුදුන් වහන්සේ මිනිස් රුවකින් නොපෙන්වා නිරූපණය කළේ කෙසේද?", "බෝධිය, ධර්මචක්‍රය හා සිරිපතුල", "කළු රවුමක් මගින් පමණක්", "කුරුස ලකුණක් මගින්", "විශාල හිස් පිළිමයක් මගින්", "මුල් යුගයේ හීනයාන සම්ප්‍රදායේදී බුදුන් වහන්සේ මිනිස් රුවින් නොදක්වා සංකේත මගින් පමණක් දැක්වීය."),
        q("සාංචි තොරණවල කෙළවර එල්ලෙන ආකාරයෙන් කැටයම් කර ඇති අඹ ගසක අත්තක් අල්ලාගෙන සිටින සුන්දර ස්ත්‍රී මූර්තිය කුමක්ද?", "ශාලභංජිකා හෙවත් වෘක්ෂ දේවතාවිය", "ගංගා දේවිය", "සීගිරි ලලනාව", "තාරා දේවිය", "සශ්‍රීකත්වයේ සංකේතයක් ලෙස සාංචි නැගෙනහිර තොරණේ කැටයම් කළ ශාලභංජිකා රුව අතිශය ප්‍රකටය."),
        q("ඉන්දියාවේ ක්‍රි.ව. 1–3 සියවස්වලදී බුදු පිළිම නෙළීම ආරම්භ වූ ප්‍රධාන කලා ගුරුකුල දෙක මොනවාද?", "ගන්ධාර සහ මථුරා කලා ගුරුකුල", "මිසර සහ බැබිලෝනියා", "මිං සහ ටැං", "පුනරුද සහ බැරොක්", "කුෂාණ රාජ්‍ය සමයේදී වයඹදිග ගන්ධාරයේත් උතුරු ඉන්දියාවේ මථුරාවේත් මුල් බුදු පිළිම බිහිවිය."),
        q("ගන්ධාර බුදු පිළිම කලාව කෙරෙහි ප්‍රබලව බලපෑ විදේශීය කලා සම්ප්‍රදාය කුමක්ද?", "ග්‍රීක හා රෝම (Greco-Roman) කලා ආභාසය", "ජපන් සෙන් කලාව", "මහනුවර ජන කලාව", "මධ්‍යකාලීන ගොතික් කලාව", "ඇපොලෝ දෙවියන්ගේ මුහුණට සමාන නාසය, රැලි ගැසුණු හිසකෙස් හා ගැඹුරු සිවුරු රැලි ග්‍රීක ආභාසය පෙන්වයි."),
        q("ගන්ධාර කලා සම්ප්‍රදායේ බුදු පිළිම නිර්මාණය කිරීම සඳහා බහුලව යොදාගත් ගල් වර්ගය කුමක්ද?", "අළු හෝ නිල් ශිලාමය ගල", "රතු තිත් වැලිගල", "සුදු කිරිගරුඬ ගල", "ලී හා මැටි පමණක්", "වර්තමාන පකිස්තාන-ඇෆ්ගන් කලාපයේ හමුවන අළු ශිස්ට් ගලින් ගන්ධාර මූර්ති නෙළා ඇත."),
        q("ගන්ධාර බුදු පිළිම හා සසඳන විට 'මථුරා' බුදු පිළිම සම්ප්‍රදායේ ප්‍රධාන ද්‍රව්‍යමය හා ශෛලීය ලක්ෂණය කුමක්ද?", "රතු වැලිගල හා පළල් උරහිස්", "අළු ගලින් නෙළූ ග්‍රීක රුව", "ලෝකඩ වාත්තු පමණක් වීම", "දැව කැටයමින් නිමවීම", "මථුරා පිළිම සම්පූර්ණ දේශීය ඉන්දීය යක්ෂ ප්‍රතිමා සම්ප්‍රදාය අනුව රතු වැලිගලින් නිමවීය."),
        q("දකුණු ඉන්දියාවේ ආන්ද්‍රා ප්‍රදේශයේ ක්‍රිෂ්ණා ගංගා නිම්නයේ බිහි වූ සුප්‍රකට බෞද්ධ මූර්ති සම්ප්‍රදාය කුමක්ද?", "අමරාවතී කලා සම්ප්‍රදාය", "හරප්පා කලා සම්ප්‍රදාය", "චෝල ලෝකඩ සම්ප්‍රදාය", "රාජපුත් සම්ප්‍රදාය", "සුදු හුණුගලින් හෙවත් පළිඟු කිරිගරුඬ වැනි ගලින් ඉතා සංකීර්ණ ජනාකීර්ණ කතා අමරාවතියේ නෙළා ඇත."),
        q("අමරාවතී මූර්ති කලාව ශ්‍රී ලංකාවේ කුමන යුගයේ මූර්ති හා කලා නිර්මාණ කෙරෙහි සෘජු බලපෑමක් කළේද?", "මුල් අනුරාධපුර යුගයේ (වාහල්කඩ හා මුල් බුදු පිළිම)", "මහනුවර යුගයේ ලාක්ෂා කලාව", "බ්‍රිතාන්‍ය යුගයේ චිත්‍ර", "ප්‍රාග් ඓතිහාසික ගල් ලෙන්", "මහාථූපය හා කන්තක චේතිය ආදී මුල් අනුරාධපුර ස්තූප කැටයම් හා බුදු පිළිමවලට අමරාවතී ආභාසය ලැබුණි."),
        q("ඉන්දීය කලාවේ 'ස්වර්ණමය යුගය' (Golden Age) ලෙස සැලකෙන්නේ කුමන රාජවංශ යුගයද?", "ගුප්ත යුගය (ක්‍රි.ව. 4–6 සියවස්)", "මෞර්ය යුගය", "බ්‍රිතාන්‍ය යුගය", "මෝගල් යුගය", "සාරානාත් හිඳි බුදු පිළිමය, අජන්තා සිතුවම් හා දේවගාර් දේවාලය ආදිය ගුප්ත ස්වර්ණමය යුගයේ බිහිවිය."),
        q("සාරානාත් කෞතුකාගාරයේ ඇති ගුප්ත යුගයට අයත් 'ධර්මචක්‍ර ප්‍රවර්තන මුද්‍රාවෙන්' යුත් හිඳි බුදු පිළිමයේ සිවුර දක්වා ඇත්තේ කෙසේද?", "ඇඟට ඇලුණු සිනිඳු විනිවිද සළුව", "ගැඹුරු රැලි ගොඩක් සහිතව", "කළු රේඛා කොටු ලෙස", "පිටුපසින් ගැට ගැසූ ලෙස", "තෙත් වූ සිවුරක් මෙන් සිරුරේ සුමට බව ඉස්මතු වන සේ අතිශය ශාන්ත ගුප්ත ශෛලියෙන් නෙළා ඇත."),
        q("මහාරාෂ්ට්‍ර ප්‍රාන්තයේ අශ්ව ලාඩමක හැඩයට පිහිටි පර්වත බිත්තියක කැන ඇති ලෝක උරුම බෞද්ධ ලෙන් විහාර පද්ධතිය කුමක්ද?", "අජන්තා ලෙන් විහාර", "එල්ලෝරා හින්දු ලෙන්", "කජුරාහෝ දේවාල", "තාජ් මහල් මන්දිරය", "වගෝරා ගඟ වංගුවේ පිහිටි ලෙන් 30කින් යුත් අජන්තා සංකීර්ණය පැරණි ඉන්දීය බෞද්ධ සිතුවමේ මහා කෞතුකාගාරයයි."),
        q("අජන්තා ලෙන් අංක 1 හි දැකිය හැකි ලෝක ප්‍රකට සිතුවම් යුගලය කවරේද?", "පද්මපාණි බෝධිසත්ව සහ වජ්‍රපාණි බෝධිසත්ව සිතුවම්", "නටරාජා සහ පාර්වතී", "සීගිරි ලලනාවන් දෙදෙනා", "මොනාලිසා සහ ඩේවිඩ්", "දකුණු අතෙහි නෙළුම් මලක් දරා ත්‍රිභංග ඉරියව්වෙන් සිටින පද්මපාණි රුව අජන්තා කලාවේ මුදුන් මල්කඩයි."),
        q("අජන්තා බිතුසිතුවම්වල බහුලව දැකිය හැකි බෝධිසත්ව හා ස්ත්‍රී රූපවල ශරීරය තුන් තැනකින් නැවී තිබීම හඳුන්වන නම කුමක්ද?", "ත්‍රිභංග ඉරියව්ව", "සමභංග ඉරියව්ව", "පද්මාසනය", "වීරාසනය", "හිස, ඉඟ හා දණහිස යන ස්ථාන තුනෙන් සියුම්ව නැවී ලාලිත්‍යය පෙන්වන ඉරියව්ව ත්‍රිභංග ඉරියව්වයි."),
        q("අජන්තා සිතුවම් සඳහා බිත්තියේ බදාමය සකස් කළ මාධ්‍ය ක්‍රමය (Tempera on Dry Plaster) හඳුන්වන්නේ කෙසේද?", "ෆ්‍රෙස්කෝ සෙකෝ (වියළි බදාමය)", "තෙත් හුණු ෆ්‍රෙස්කෝ බුඕනෝ", "කැන්වස් තෙල් සායම්", "ඇක්‍රිලික් ඉසීම", "ගොම, මැටි හා කුඩු කළ හුණු තට්ටු මත වියළුණු පසු ඛනිජ වර්ණවලින් අජන්තා සිතුවම් ඇඳ ඇත."),
        q("අජන්තා ලෙන් විහාර අතර 'චෛත්‍යඝර' (Chaitya Hall) සහ 'විහාර' (Vihara) යන ගොඩනැගිලි වර්ග දෙකේ වෙනස කුමක්ද?", "චෛත්‍යඝරය පූජාවට, විහාරය වාසයට", "දෙකම රජ මාලිගා වේ", "චෛත්‍යඝරය මුළුතැන්ගෙය වේ", "විහාරය සතුන් ගාල් කරන තැනකි", "ඇතුළත ස්තූපයක් ඇති ආරුක්කු ශාලාව චෛත්‍යය වන අතර වටේ කුටි ඇති මැද ශාලාව විහාරයයි."),
        q("අජන්තා ලෙන් විහාර කලාව ශ්‍රී ලංකාවේ කුමන බිතුසිතුවම් සම්ප්‍රදායට ශෛලිමය වශයෙන් වඩාත් සමීපද?", "සීගිරි බිතුසිතුවම් සම්ප්‍රදායට", "මහනුවර පහතරට සිතුවම්වලට", "බ්‍රිතාන්‍ය ජල සායම්වලට", "ප්‍රාග් ඓතිහාසික ගල් කෙටුම්වලට", "වර්ණ සංකලනය, රේඛා ලාලිත්‍යය හා ත්‍රිමාණ බව අතින් සීගිරි සිතුවම් අජන්තා ගුප්ත සම්ප්‍රදායට නෑකම් කියයි."),
        q("ඉන්දියාවේ බෞද්ධ, හින්දු සහ ජෛන යන ආගම් තුනටම අයත් ලෙන් කැටයම් එකම පර්වත පෙළක පිහිටි ලෝක උරුමය කුමක්ද?", "එල්ලෝරා ලෙන් සංකීර්ණය", "තක්ෂිලා විශ්වවිද්‍යාලය", "භාරුත් ස්තූපය", "මොහෙන්ජො-දාරෝ නගරය", "ලෙන් 34කින් යුත් එල්ලෝරාහි බෞද්ධ ලෙන් 12ක්, හින්දු ලෙන් 17ක් සහ ජෛන ලෙන් 5ක් පිහිටයි."),
        q("එල්ලෝරා හි පිහිටි තනි කළුගල් කන්දක් ඉහළ සිට පහළට හාරා නෙළන ලද ලෝකයේ විශාලතම ඒකශෛලමය දේවාලය කුමක්ද?", "කෛලාසනාථ දේවාලය (ලෙන් අංක 16)", "බෘහදීශ්වර දේවාලය", "සූර්ය දේවාලය", "ගඩලාදෙණිය විහාරය", "රාෂ්ට්‍රකූට යුගයේ කෘෂ්ණ රජු සමයේ කළුගල් කන්ද උඩ සිට පහළට කපා මෙම විස්මිත දේවාලය නිමවීය."),
        q("මුම්බායි අසල දූපතක පිහිටි 'එලිෆන්ටා ලෙනෙහි' (Elephanta Caves) ඇති අතිශය ප්‍රසිද්ධ දැවැන්ත මූර්තිය කුමක්ද?", "ත්‍රිමූර්ති ශිව (මහේෂමූර්ති) ප්‍රතිමාව", "නටන ගනේෂ ප්‍රතිමාව", "ගෞතම බුදු පිළිමය", "විෂ්ණුගේ මත්ස්‍ය අවතාරය", "සද්යෝජාත, අඝෝර හා වාමදේව යන ශිවගේ මුහුණු තුන දැක්වෙන මීටර් 6ක් උස ත්‍රිමූර්ති කැටයම ප්‍රකටය."),
        q("දකුණු ඉන්දියාවේ තමිල්නාඩු වෙරළේ 'මහාබලිපුරම්' (මාමල්ලපුරම්) හි පල්ලව රාජවංශය කළ විශාල ගල් තලාවේ අර්ධ උන්නත කැටයම කුමක්ද?", "ගංගාවතරණය හෙවත් අර්ජුන තපස", "කුරුක්ෂේත්‍ර මහා යුද්ධය", "රාවණා ඇල්ල කැටයම", "මාතා දේවී ප්‍රතිමාව", "දේව, නාග, මිනිස් හා ඇත් රූප සිය ගණනක් පර්වත පෘෂ්ඨය පුරා නෙළා ඇති විශිෂ්ට පල්ලව කැටයමකි."),
        q("මහාබලිපුරම් හි වෙරළබඩ ගල් කුට්ටි කපා ඉදි කළ පංච පාණ්ඩව රථ පහ අයත් වන්නේ කුමන ඉන්දීය කලා සම්ප්‍රදායටද?", "පල්ලව කලා සම්ප්‍රදායට", "මෞර්ය කලා සම්ප්‍රදායට", "මෝගල් කලා සම්ප්‍රදායට", "සින්ධු නිම්න සම්ප්‍රදායට", "තනි ග්‍රැනයිට් ගල් කුට්ටිවලින් පංච රථ හා වෙරළ දේවාලය තැනීම පල්ලව ද්‍රවිඩ වාස්තු කලාවේ ආරම්භයයි."),
        q("ලොව පුරා අතිශය ජනප්‍රිය 'නටරාජා' (නටන ශිව) ලෝකඩ ප්‍රතිමාව විශිෂ්ටත්වයට පත් වූයේ කුමන දකුණු ඉන්දීය රාජවංශ සමයේද?", "චෝල රාජවංශ සමයේ", "මෞර්ය යුගයේ", "ඉන්දු නිම්න යුගයේ", "බ්‍රිතාන්‍ය යුගයේ", "ගිනි වළල්ලක් මැද නර්තනයේ යෙදෙන චෝල ලෝකඩ නටරාජා ප්‍රතිමාව ශ්‍රී ලංකාවේ පොළොන්නරුවෙන්ද හමුවී ඇත."),
        q("චෝල නටරාජා ප්‍රතිමාවේ ශිව දෙවියන්ගේ දකුණු පයට යටින් පෑගී සිටින කුරු මිනිස් රුවෙන් සංකේතවත් කරන්නේ කුමක්ද?", "අවිද්‍යාව (අපස්මාර පුරුෂයා)", "කාලය හා අභ්‍යවකාශය", "වර්ෂාව හා සුළඟ", "ධනය හා බලය", "අඥානකම මැඩලමින් සිදු කරන විශ්ව නර්තනය (ආනන්ද තාණ්ඩව) අපස්මාර මත සිට දැක්වේ."),
        q("චෝල නටරාජා මූර්තියේ වටා ඇති ගිනිදැල් වළල්ලෙන් හා අතක ඇති කුඩා උඩැක්කියෙන් (ඩමරුව) නිරූපණය කරන්නේ කුමක්ද?", "විශ්වයේ නිර්මාණය, නාදය හා චක්‍රීය විනාශය", "රාජ්‍ය යුද ජයග්‍රහණය", "සංගීත පාසලේ නාම පුවරුව", "ගෘහ නිර්මාණ ශිල්පියාගේ මුද්‍රාව", "ඩමරුව මැවීමේ නාදයද, අභය මුද්‍රාව ආරක්ෂාවද, ගින්න විනාශය හා නව ආරම්භයද දක්වයි."),
        q("මධ්‍යකාලීන ඉන්දියාවේ ඔඩීෂා ප්‍රාන්තයේ 'කොනාරක් සූර්ය දේවාලය' නිර්මාණය කර ඇත්තේ කුමන ස්වරූපයකටද?", "ගල් රෝද 24 හා අසුන් 7 හිරු රථය", "දැවැන්ත නෙළුම් පොහොට්ටුවක් ලෙස", "පිරමීඩ හතරක් ලෙස", "වක්‍ර වූ නැවක් ලෙස", "13 වන සියවසේ ඉදි වූ කොනාරක් දේවාලයේ කළුගල් රෝද විසිහතර පැය ගණන හා දවසේ කාලය පෙන්වයි."),
        q("ඉන්දියාවේ තන්ජාවූර් හි පිහිටි චෝල යුගයේ උසම ගල් විමාන කුළුණ (මීටර් 66ක් උස) සහිත දේවාලය කුමක්ද?", "බෘහදීශ්වර (රාජරාජේශ්වර) දේවාලය", "සාංචි මහා ස්තූපය", "කජුරාහෝ දේවාලය", "කාර්ලේ චෛත්‍යය", "පළමුවන රාජරාජ චෝල රජු තැනූ බෘහදීශ්වර දේවාලය ද්‍රවිඩ කෝවිල් ගෘහ නිර්මාණයේ මුදුන් මල්කඩයි."),
        q("16–17 සියවස්වල ඉන්දියාවේ විකාශනය වූ 'මෝගල් ක්ෂුද්‍ර චිත්‍ර කලාවේ' (Mughal Miniature Painting) විශේෂ ලක්ෂණය කුමක්ද?", "සියුම් පොත් චිත්‍ර හා රාජ සභා", "පර්වත මත සෙවණැලි ඇඳීම", "වියුක්ත කළු-සුදු තීන්ත පැල්ලම්", "තෙල් සායම් බිත්ති සිතුවම්", "අක්බර් හා ජහන්ගීර් අධිරාජ්‍ය සමයන්හි ඉතා සියුම් පින්සලෙන් රාජකීය පොත් අලංකාර කළහ."),
        q("මෝගල් වාස්තු කලාවේ ලෝක පූජිත අග්‍රගණ්‍ය නිර්මාණය වන 'ටජ් මහල්' මන්දිරය ඉදි කළ අධිරාජ්‍යයා කවුද?", "ෂා ජහන් අධිරාජ්‍යයා", "අශෝක අධිරාජ්‍යයා", "චන්ද්‍රගුප්ත මෞර්ය", "ශිවාජි මහරජු", "මුම්ටාස් මහල් බිසව සිහිවීම සඳහා යමුනා ගං තෙරේ සුදු මාබල්වලින් ෂා ජහන් රජු ටජ් මහල් ඉදි කළේය."),
        q("ටජ් මහල් මන්දිරයේ ගෘහ නිර්මාණයේ කැපී පෙනෙන 'පියෙට්රා ඩූරා' (Pietra Dura) කලා ශිල්පය යනු කුමක්ද?", "සුදු මාබල් මත මැණික් මල් රටා", "කළු තීන්තෙන් බිත්ති ලිවීම", "මැටි පුළුස්සා වහලය සෙවිලි කිරීම", "පිත්තල තහඩු ඇණ ගැසීම", "අගනා වෛරෝඩි, රතු ගල් හා ජේඩ් කැබලි කපා කිරිගරුඬ මත ඔබ්බවා සියුම් මල් රටා මැවීමයි."),
        q("මෝගල් කලාවට සමගාමීව රාජස්ථාන හා පහාරි ප්‍රදේශවල වර්ධනය වූ 'රාජ්පුත් ක්ෂුද්‍ර චිත්‍රවල' ප්‍රධාන තේමාවන් මොනවාද?", "කෘෂ්ණ-රාධා ප්‍රේම කතා, රාමායණය, රාගමාලා සංගීතය හා සෘතු භේදය", "මෝගල් යුද සැලසුම් පමණක්", "කාර්මික නගර නිර්මාණය", "බ්‍රිතාන්‍ය දේශපාලන කාටූන්", "දීප්තිමත් රතු, කහ හා නිල් වර්ණවලින් හින්දු ආගමික හා කාව්‍ය තේමා රාජ්පුත් සිතුවම්වල දැක්වේ."),
        q("චීන සාම්ප්‍රදායික චිත්‍ර කලාවේ (Chinese Painting) වඩාත් උසස් ලෙස සලකන චිත්‍ර වර්ගය කුමක්ද?", "ශාන්-ශුයි කඳු-ජල භූ දර්ශන", "ත්‍රිමාණ මිනිස් නිරුවත් ප්‍රතිමා", "වර්ණවත් පොප් කලා පෝස්ටර්", "ලෝහ කොලාජ් චිත්‍ර", "මිනිසා හා සොබාදහම අතර තාඕවාදී සමතුලිතතාව පෙන්වන කඳු-දිය භූ දර්ශන චීන කලාවේ මුදුනත වේ."),
        q("චීන චිත්‍ර කලාවේ සුප්‍රකට 'මොනොක්‍රෝම් තීන්ත චිත්‍ර' (Ink Wash Painting) සඳහා භාවිත කළ ප්‍රධාන ද්‍රව්‍ය මොනවාද?", "චීන තීන්ත කූර, උණ පින්සල, සේද", "තෙල් සායම් හා පැලට් පිහිය", "පැස්ටල් කූරු හා කළු ලෑල්ල", "ගුරුගල් හා ගොම බදාම", "පින් ගලක තීන්ත කූර ඇඹරීමෙන් සකසා ගන්නා කළු තීන්ත ජලය සමඟ තනුක කර විවිධ අඳුරු-එළි මට්ටම් මවයි."),
        q("ක්‍රි.ව. 6 වන සියවසේ චීන කලා විචාරක 'ෂී හේ' (Xie He) විසින් ඉදිරිපත් කළ චීන චිත්‍ර කලාවේ මූලික රීති පද්ධතිය කුමක්ද?", "චිත්‍රයේ සය වැදෑරුම් මූලධර්ම", "ත්‍රිභංග මූර්ති රීතිය", "රන්මය අනුපාත නියමය", "ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය", "ෂී හේ ඉදිරිපත් කළ මූලධර්ම හයෙන් පළමු වැන්න වන්නේ ජීව ගුණය හා චලන රිද්මය (Qi Yun) රැඳවීමයි."),
        q("චීන චිත්‍ර කලාවේ සදාතනිකව ඒකාබද්ධ වූ 'පරිපූර්ණත්ව තුන' (Three Perfections) ලෙස හඳුන්වන්නේ කුමන කලාවන්ද?", "චිත්‍ර කලාව, කවිය සහ අක්ෂර කලාව (Calligraphy)", "මූර්ති, වාස්තු සහ කැටයම්", "සංගීතය, නැටුම් සහ නාට්‍ය", "ලෝකඩ, මැටි සහ රෙදි", "සාම්ප්‍රදායික චීන අකුරු ලියන රෝල් චිත්‍රයක සිතුවම සමඟ කවියක් හා රතු මුද්‍රාවක්ද ඇතුළත් වේ."),
        q("චීනයේ සේද රෙදි හෝ කඩදාසි මත ඇඳි චිත්‍රය අවසානයේ ශිල්පියා විසින් තබන රතු පැහැති අත්සන් සලකුණ කුමක්ද?", "චොප් හෙවත් රතු තීන්ත මුද්‍රාව", "පෑන් අත්සන", "කළු ඇඟිලි සලකුණ", "රන් කාසිය", "ජේඩ් හෝ සබන් ගලින් කැපූ කලාකරුගේ නම සහිත රතු මුද්‍රාව චිත්‍රයේ සංයුතිය සම්පූර්ණ කරයි."),
        q("චීනයේ සාම්ප්‍රදායික සිතුවම් කලාවේ 'මහත්වරුන්ගේ සිව් පැළෑටි' (Four Gentlemen) ලෙස බහුලව අඳින ස්වභාවික තේමා හතර මොනවාද?", "උණ බට, ඕකිඩ්, ප්ලම් මල් සහ ක්‍රිසැන්තිමම් මල", "රෝස, පොල්, කෙසෙල් සහ පතොක්", "නෙළුම්, මානෙල්, ඕලු සහ සල්", "කොස්, දෙල්, අඹ සහ දිවුල්", "කන්න හතර හා උතුම් මානව ගුණාංග සංකේතවත් කිරීමට මෙම ශාක හතර චීන තීන්ත පින්සලෙන් පුහුණු කෙරේ."),
        q("චීනයේ ෂියෑන් (Xi'an) නගරයෙන් හමුවූ ක්වින් ශි හුවාං අධිරාජ්‍යයාගේ සොහොන් ගැබ රකින යෝධ හමුදාව කුමක්ද?", "ටෙරාකොටා යුධ හමුදාව (Terracotta Army)", "රන් මිනිස් ප්‍රතිමා සියය", "කිරිගරුඬ දේවදූතයන්", "ලෝකඩ අශ්ව රථ සේනාව", "ක්‍රි.පූ. 210 දී පමණ පිළිස්සූ මැටියෙන් තැනූ ජීවමාන ප්‍රමාණයේ සොල්දාදුවන් 8000කට අධික ප්‍රතිමා මෙහි වේ."),
        q("චීනයේ ටෙරාකොටා යුධ හමුදාවේ ඇති සුවිශේෂී කලාත්මක විස්මය කුමක්ද?", "සෑම සොල්දාදුවෙකුගේම මුහුණු ඉරියව්, රැවුල් හා හිසකෙස් එකිනෙකට වෙනස් ලෙස අඹා තිබීම", "සියල්ලම එකම අච්චුවෙන් කළ සමාන මුහුණු වීම", "ඒවා සෙන්ටිමීටර 5ක් පමණ කුඩා වීම", "සියල්ල සජීවී මිනිසුන්ට මැටි ගා සෑදීම", "සිරුරු කොටස් අච්චුවෙන් සෑදුවද මුහුණු හා ප්‍රකාශන අතින් වෙනස් කර අද්විතීය පෞරුෂ මවා ඇත."),
        q("චීන සෙරමික් හෙවත් පිඟන් මැටි කලාවේ 'මිං රාජවංශය' (Ming Dynasty) ලෝක ප්‍රසිද්ධ වී ඇත්තේ කුමන නිර්මාණ සඳහාද?", "කොබෝල්ට් නිල්-සුදු පෝසිලේන්", "රළු නොපිළිස්සූ කළු මැටි හට්ටි", "තඹ සහ යකඩ මුට්ටි", "වීදුරු බෝතල් පමණක්", "අධික උෂ්ණත්වයේ පිළිස්සූ සියුම් පෝසිලේන් මත කොබෝල්ට් නිල් මකර හා මල් රටා මිං යුගයේ සංකේතයකි."),
        q("චීනයේ බෞද්ධ ගල් ලෙන් කලාවේ ප්‍රධානතම කේන්ද්‍රස්ථානය ලෙස සැලකෙන ගෝබි කාන්තාරය අසල පිහිටි ලෙන් පද්ධතිය කුමක්ද?", "දුන්හුවාං මොගාඕ ලෙන් (Mogao Caves)", "සීගිරි ලෙන්", "අජන්තා ලෙන්", "බාමියන් ලෙන්", "සේද මාවත ඔස්සේ බුදු දහම චීනයට පැතිර යාමේදී දහස් ගණන් බිතුසිතුවම් හා මූර්ති මොගාඕ ලෙන්වල නිමවීය."),
        q("17–19 සියවස්වල ජපානයේ එඩෝ (Edo) යුගයේ ජනප්‍රිය වූ 'උකියෝ-ඒ' (Ukiyo-e) කලා මාධ්‍යය කුමක්ද?", "ලී කුට්ටි මුද්‍රණ කලාව", "කළුගල් කැටයම් කලාව", "තෙල් සායම් කැන්වස් චිත්‍ර", "වීදුරු කැටයම් මොසැයික්", "පාවෙන ලෝකයේ සිතුවම් යන අරුතැති උකියෝ-ඒ ජපන් මධ්‍යම පාන්තික ජනයා අතර ලී මුද්‍රණ මගින් ජනප්‍රිය විය."),
        q("ජපන් උකියෝ-ඒ ලී කුට්ටි මුද්‍රණ කලාවේ වඩාත්ම ප්‍රසිද්ධ කලා කෘතිය වන 'කනගාවා හි මහා රළ පහර' (The Great Wave off Kanagawa) නිර්මාණය කළ ශිල්පියා කවුද?", "කත්සුෂිකා හොකුසායි", "ලියනාඩෝ ඩා වින්චි", "ඇන්ඩැගාවා හිරෝෂිගේ", "ක්ලෝඩ් මොනේ", "ෆුජි කන්ද පසුබිමේ තබා දැවැන්ත රළ පහර සහ ධීවර ඔරු දක්වන හොකුසායිගේ කෘතිය ලොව සුප්‍රකටය."),
        q("ජපන් ලී මුද්‍රණ ශිල්පියෙකු වූ 'උතගාවා හිරෝෂිගේ' (Utagawa Hiroshige) විශේෂයෙන් ප්‍රසිද්ධියට පත් වූ තේමාව කුමක්ද?", "ටොකයිඩෝ නැවතුම්පොළ 53 භූ දර්ශන", "යුද රථ සහ යුද බිම්", "රාජකීය පුද්ගල ආලේඛ්‍ය", "නූතන අහස උස ගොඩනැගිලි", "සොබාදහමේ කාලගුණික විපර්යාස හා සංචාරක දර්ශන සියුම් වර්ණ සංක්‍රාන්ති මගින් හිරෝෂිගේ මුද්‍රණය කළේය."),
        q("ජපන් උකියෝ-ඒ මුද්‍රණ කෘති 19 වන සියවසේදී යුරෝපයට පැමිණීමෙන් බටහිර කුමන නූතන චිත්‍ර ව්‍යාපාර කෙරෙහි ප්‍රබල ආභාසයක් ඇති කළේද?", "උපස්ථිතිවාදය හා පශ්චාත් උපස්ථිතිවාදය", "ග්‍රීක සම්භාව්‍ය කලාව", "මිසර බිතුසිතුවම්", "මධ්‍යකාලීන බයිසැන්ටයින් කලාව", "මොනේ, ඩෙගාස් හා වෑන් ගෝ වැනි යුරෝපීය චිත්‍ර ශිල්පීන් ජපන් කලාවේ පැතලි වර්ණ හා අසමමිතික රාමු අගය කළහ."),
        q("ජපානයේ 'සෙන් බුදුදහම' (Zen Buddhism) හා බැඳුණු කලාත්මක 'වියළි භූ දර්ශන උද්‍යාන' (Zen Rock Garden / Karesansui) වල යොදා ගන්නා ප්‍රධාන ද්‍රව්‍ය මොනවාද?", "සිනිඳු රේක්ක කළ සුදු බොරළු සහ ස්වභාවික ගල් පර්වත", "වර්ණවත් ප්ලාස්ටික් මල්", "දැවැන්ත කිරිගරුඬ ප්‍රතිමා", "විදුලි වතුර මල් සහ නියොන් බල්බ", "කියෝතෝහි රියෝආන්-ජි උද්‍යානය මෙන් රැලි ආකාරයෙන් පීරූ සුදු වැලි හා ගල් භාවනාමය සන්සුන් බව මවයි."),
        q("ජපන් සෙන් චිත්‍ර කලාවේ එකම පින්සල් පහරකින් හෝ පහර කිහිපයකින් අඳින පරිපූර්ණත්වය හා හිස්බව සංකේතවත් කරන වෘත්තය කුමක්ද?", "එන්සෝ (Enso)", "මණ්ඩලය", "සඳකඩපහණ", "හංස පූට්ටුව", "සෙන් භික්ෂූන් හිත එකඟ කර එක හුස්මකින් අඳින කළු තීන්ත වෘත්තය එන්සෝ නම් වේ."),
        q("චීන හා ජපන් කලාවේ පසුබිමේ විශාල 'හිස් ඉඩක්' (Negative Space) ඉතිරි කිරීම මගින් අදහස් කරන්නේ කුමක්ද?", "නරඹන්නාගේ මනසට නිදහස, නිශ්ශබ්දතාව හා අසීමිත අවකාශය දැනවීම", "තීන්ත අවසන් වීම නිසා නතර කිරීම", "ශිල්පියාගේ කම්මැලිකම", "බිත්තිය ඉරිතැළී තිබීම", "බටහිර කලාවේ මුළු පසුබිම පිරවීමට වෙනස්ව පෙරදිග කලාවේ හිස් අවකාශය මීදුම, අහස හෝ ජලය නියෝජනය කරයි."),
        q("ජපානයේ සාම්ප්‍රදායික කඩදාසි නැවීමේ කලාව සහ බිඳුණු මැටි බඳුන් රත්තරන් මැලියමින් පෑස්සීමේ කලාව පිළිවෙලින් මොනවාද?", "ඔරිගාමි (Origami) සහ කින්ට්සුගි (Kintsugi)", "බතික් සහ ලාක්ෂා", "ෆ්‍රෙස්කෝ සහ මොසැයික්", "කොලාජ් සහ ලිනෝ කට්", "කඩදාසි නැවීම ඔරිගාමි වන අතර කැඩුණු සෙරමික් බඳුන් රන් කුඩු මිශ්‍ර ලාටුවෙන් ඇලවීම කින්ට්සුගි වේ."),
        q("අග්නිදිග ආසියාවේ ඉන්දුනීසියාවේ පිහිටි ලෝකයේ විශාලතම බෞද්ධ ස්මාරකය වන මහායාන ස්තූප සංකීර්ණය කුමක්ද?", "බෝරෝබුදූර් (Borobudur)", "සාංචි ස්තූපය", "අංකෝර් වත්", "ප්‍රම්බනන්", "9 වන සියවසේ ජාවා දූපතේ ශෛලේන්ද්‍ර රජවරුන් තැනූ බෝරෝබුදූර් මළු නවයකින් හා ස්තූප 72කින් යුක්තය."),
        q("කාම්බෝජයේ 12 වන සියවසේ ඉදි කරන ලද ලෝකයේ විශාලතම ආගමික ස්මාරක සංකීර්ණය වන්නේ කුමක්ද?", "අංකෝර් වත් (Angkor Wat)", "බෝරෝබුදූර්", "බාමියන් පිළිම", "ටජ් මහල්", "දෙවන සූර්යවර්මන් රජු මුලින් විෂ්ණු දේවාලයක් ලෙස තැනූ අංකෝර් වත් පසුව බෞද්ධ පූජනීය ස්ථානයක් විය."),
        q("ජපානයේ හෝර්යු-ජි (Horyu-ji) හා තෝදායි-ජි (Todai-ji) විහාර වාස්තු කලාව සැලකෙන්නේ කුමන අතින්ද?", "පැරණිතම දැව පැගෝඩා හා විහාර", "කළුගල් පිරමීඩ ලෙස", "රෝම කොලෝසියමට සමාන වීම නිසා", "භූගත ලෝහ බංකර් ලෙස", "ජපන් භූමිකම්පාවලට ඔරොත්තු දෙන අන්තර් සම්බන්ධිත දැව කුළුණු ක්‍රමයෙන් පැරණි පැගෝඩා ඉදි කර ඇත."),
        q("චීන කැලිග්‍රැෆි (Calligraphy) හෙවත් සුන්දර අක්ෂර ලිවීමේ කලාවේ 'අධ්‍යයන කාමරයේ සිව් වස්තුව' (Four Treasures of the Study) මොනවාද?", "පින්සල, තීන්ත කූර, කඩදාසි සහ තීන්ත අඹරන ගල", "කියත, මිටිය, නියන සහ කෝදුව", "මැටි, ජලය, ගින්න සහ අච්චුව", "කැමරාව, ලෙන්සය, කාඩ්පත සහ විදුලි ආලෝකය", "සාම්ප්‍රදායික චීන පඬිවරයෙකුගේ මේසයේ පින්සල, තීන්ත, සුආන් කඩදාසි හා තීන්ත ගල අනිවාර්ය විය."),
        q("ඉන්දියාවේ කජුරාහෝ (Khajuraho) දේවාල සංකීර්ණය කුමන රාජවංශ කාලයේදී නාගර (Nagara) ශෛලියෙන් ඉදි කරන ලද්දක්ද?", "චන්දේල රාජවංශ සමයේ", "මෞර්ය රාජවංශ සමයේ", "බ්‍රිතාන්‍ය සමයේ", "පල්ලව සමයේ", "උතුරු ඉන්දීය නාගර ශෛලියේ උස් ශිඛර සහිත කජුරාහෝ දේවාල චන්දේල රජවරුන් විසින් ඉදි කෙරිණි."),
        q("පෙරදිග ආසියාතික චිත්‍ර කලාව බටහිර සම්භාව්‍ය චිත්‍ර කලාවෙන් මූලිකවම වෙනස් වන දෘෂ්ටිමය ලක්ෂණයක් කුමක්ද?", "ඒකලක්ෂ්‍ය රේඛීය දෘෂ්ටිකෝණය වෙනුවට බහු දෘෂ්ටිකෝණ හා රේඛීය රිද්මය අගය කිරීම", "කිසිදු වර්ණයක් හෝ තීන්තක් නොයෙදීම", "රාමු කළ කැන්වස් පමණක් භාවිතය", "මානව ඇටසැකිලි මිනුම් පමණක් යෙදීම", "චීන ලියවිලි රෝලක දර්ශනය උස හා දුර අනුව විවිධ දෘෂ්ටි කෝණවලින් ගලා යාම පෙරදිග විශේෂත්වයකි."),
        q("චීන කුඹල් කලාවේ ඉහළම තාක්ෂණික නිමැවුමක් වන 'සෙලඩොන්' (Celadon) පිඟන් බඩුවල ඇති සුවිශේෂී වර්ණය කුමක්ද?", "ජේඩ් මැණිකට සමාන ලා කොළ-නිල් (ඇල් කොළ) වර්ණය", "දීප්තිමත් තැඹිලි වර්ණය", "තද කළු කාබන් වර්ණය", "රෝස මිශ්‍ර දම් වර්ණය", "යකඩ ඔක්සයිඩ් මිශ්‍ර ඔපය අඩු ඔක්සිජන් තත්ත්වයේ පිළිස්සීමෙන් අලංකාර ජේඩ් කොළ සෙලඩොන් පැහැය ලැබේ.")
    )
}
